<template><div><PageHeader title="Training calendar" description="See sessions, trainer schedules and cohort activity in one place."><template #actions><button class="btn secondary">Week</button><button class="btn primary" @click="push('New session workflow opened.')">+ New session</button></template></PageHeader><div class="card calendar"><div class="toolbar" style="padding:0 0 16px;border:0"><div class="toolbar-left"><button class="btn secondary small">‹</button><strong>September 2026</strong><button class="btn secondary small">›</button></div><div class="toolbar-right"><select class="select"><option>All trainers</option><option>Ahmed Khan</option><option>Mariam Ali</option></select></div></div><div class="cal-grid"><div v-for="d in days" :key="d" class="cal-head">{{d}}</div><div v-for="cell in cells" :key="cell.id" class="cal-day" :class="{'muted-day':cell.muted}"><div class="day-number">{{cell.day}}</div><div v-for="event in cell.events" :key="event.text" class="event" :class="event.tone">{{event.text}}</div></div></div></div></div></template>
<script setup lang="ts">import PageHeader from '../components/PageHeader.vue';import {useToast} from '../composables/useToast';const {push}=useToast();const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const events=[{text:'Laravel · 10:00',tone:''},{text:'Python · 14:00',tone:'orange'},{text:'Security · 16:30',tone:'green'}];const cells=Array.from({length:35},(_,i)=>({id:i,day:i<3?28+i:i-2,muted:i<3||i>32,events:i===17?[events[0],events[1]]:i===19?[events[2]]:i===22?[events[0]]:[]}));</script>
